def v5(n):
    count = 0
    if n == 0:
        return float('inf')
    while n > 0 and n % 5 == 0:
        count += 1
        n //= 5
    return count

def g(x):
    return 1 + 10 * v5(x)

# Calculate g(41000)
result = g(41000)
print(f"g(41000) = {result}")

